from storage_client import get_storage_client
from storage_models import UploadObjectRequest, UploadObjectResponse

def upload_object(request: UploadObjectRequest) -> UploadObjectResponse:
    client = get_storage_client()
    bucket = client.bucket(request.bucket_name)
    blob = bucket.blob(request.destination_blob_name)

    if request.file_path:
        blob.upload_from_filename(request.file_path, content_type=request.content_type)
    elif request.data:
        blob.upload_from_string(request.data, content_type=request.content_type)
    else:
        raise ValueError("Either 'file_path' or 'data' must be provided for upload.")

    blob.reload()  # Fetch updated metadata after upload

    return UploadObjectResponse(
        bucket_name=request.bucket_name,
        blob_name=request.destination_blob_name,
        public_url=blob.public_url,
        e_tag=blob.etag,
        metadata=blob.metadata
    )

from google.cloud import translate_v2 as translate
from dataclasses import dataclass
from typing import Optional, Dict, Any

@dataclass
class StoredTextTranslateRequest:
    text_to_translate: str
    target_language: str
    source_language: Optional[str] = None

@dataclass
class StoredTextTranslateResponse:
    translated_text: str
    detected_source_language: Optional[str] = None
    full_response: Optional[Dict[str, Any]] = None

def translate_stored_text(request: StoredTextTranslateRequest) -> StoredTextTranslateResponse:
    client = translate.Client()

    result = client.translate(
        request.text_to_translate,
        target_language=request.target_language,
        source_language=request.source_language
    )

    return StoredTextTranslateResponse(
        translated_text=result['translatedText'],
        detected_source_language=result.get('detectedSourceLanguage'),
        full_response=result
    )

import vertexai
from vertexai.language_models import TextEmbeddingModel
from dataclasses import dataclass
from typing import List, Dict, Any, Optional

@dataclass
class AssetMetadataEmbeddingRequest:
    texts: List[str]

@dataclass
class AssetMetadataEmbeddingResponse:
    embeddings: List[List[float]]
    full_response: Optional[Dict[str, Any]] = None

def embed_asset_metadata_and_text(request: AssetMetadataEmbeddingRequest) -> AssetMetadataEmbeddingResponse:
    # Initialize Vertex AI (you might want to move this to a central client helper)
    vertexai.init()

    model = TextEmbeddingModel.from_pretrained("text-embedding-004") # Using a concrete model identifier

    # The Vertex AI embedding model can take multiple texts in a single request
    embeddings_response = model.get_embeddings(request.texts)

    embeddings = [embedding.values for embedding in embeddings_response]

    return AssetMetadataEmbeddingResponse(embeddings=embeddings)
